SELECT o.id AS id, o.order_no AS orderNo, o.order_name AS orderName, o.business_entity_id AS businessEntityId, be.name AS businessEntityName, o.customer_id AS customerId, c.name AS customerName, o.order_type AS orderType, o.status AS status, o.total_amount AS totalAmount, o.receivable_amount AS receivableAmount, o.media_payable_amount AS mediaPayableAmount, o.rebate_amount AS rebateAmount, o.receipt_method AS receiptMethod, o.payment_method AS paymentMethod, o.delivery_start_date AS deliveryStartDate, o.delivery_end_date AS deliveryEndDate, o.creator_id AS creatorId, o.create_time AS createTime, CASE WHEN COUNT(oc.id) = 0 THEN 1 ELSE 0 END AS missingContract FROM ad_order o LEFT JOIN ad_business_entity be ON be.id = o.business_entity_id AND be.deleted = 0 LEFT JOIN ad_customer c ON c.id = o.customer_id AND c.deleted = 0 LEFT JOIN ad_order_contract oc ON oc.order_id = o.id AND oc.deleted = 0 WHERE o.organization_id = #{request.organizationId} AND o.deleted = 0
AND o.status = #{request.status}
AND o.business_entity_id = #{request.businessEntityId}
AND o.customer_id = #{request.customerId}
AND o.order_type = #{request.orderType}
AND o.receipt_method = #{request.receiptMethod}
AND o.payment_method = #{request.paymentMethod}
AND (o.order_no LIKE CONCAT('%', #{request.keyword}, '%') OR c.name LIKE CONCAT('%', #{request.keyword}, '%'))
AND o.business_entity_id IN
#{eid}
AND o.delivery_start_date >= #{request.deliveryStartFrom}
AND o.delivery_start_date <= #{request.deliveryStartTo}
GROUP BY o.id

SELECT COUNT(1)
FROM ad_order
WHERE organization_id = #{orgId}
  AND business_entity_id = #{businessEntityId}
  AND deleted = 0
  AND create_time >= #{start}
  AND create_time <= #{end}

SELECT COUNT(1)
FROM ad_order
WHERE customer_id = #{customerId}
  AND organization_id = #{orgId}
  AND deleted = 0

